"""Analyse syntaxique : transforme la liste de jetons en arbre (AST).

Technique : « descente récursive ». Chaque règle de la grammaire
(docs/specification/grammaire.ebnf) correspond à une méthode de cette classe.
"""

from . import ast
from .erreurs import ErreurSyntaxe
from .jetons import (
    DECIMAL, ENTIER, FIN_FICHIER, IDENT, MOTCLE, NL, OPERATEURS_COMPARAISON,
    SYMBOLE, TEXTE, Jeton,
)


class Parser:
    def __init__(self, jetons: list[Jeton]):
        self.jetons = jetons
        self.i = 0

    # --- outils -------------------------------------------------------------

    @property
    def courant(self) -> Jeton:
        return self.jetons[self.i]

    def avancer(self) -> Jeton:
        jeton = self.jetons[self.i]
        if jeton.type != FIN_FICHIER:
            self.i += 1
        return jeton

    def est_motcle(self, *mots) -> bool:
        return self.courant.type == MOTCLE and self.courant.valeur in mots

    def est_symbole(self, *symboles) -> bool:
        return self.courant.type == SYMBOLE and self.courant.valeur in symboles

    def est_fin_ligne(self) -> bool:
        return self.courant.type in (NL, FIN_FICHIER)

    def erreur(self, message, jeton=None, conseil=None, incomplet=None):
        jeton = jeton or self.courant
        if incomplet is None:
            incomplet = jeton.type == FIN_FICHIER
        return ErreurSyntaxe(message, jeton.ligne, jeton.colonne, conseil,
                             incomplet)

    def sauter_fins_ligne(self):
        while self.courant.type == NL:
            self.avancer()

    def attendre_motcle(self, mot, message, conseil=None) -> Jeton:
        if not self.est_motcle(mot):
            if self.est_symbole("=") and mot in ("alors", "faire"):
                conseil = ("« = » sert à donner une valeur ; "
                           "pour comparer, écrivez ==")
            raise self.erreur(
                f"{message}, mais {self.courant.decrire()} a été trouvé",
                conseil=conseil)
        return self.avancer()

    def attendre_symbole(self, symbole, message, ouvrant=None) -> Jeton:
        if not self.est_symbole(symbole):
            if self.courant.type == FIN_FICHIER and ouvrant is not None:
                raise self.erreur(
                    f"« {ouvrant.valeur} » ouvert ici n'est jamais fermé par "
                    f"« {symbole} »", jeton=ouvrant, incomplet=True)
            raise self.erreur(
                f"{message}, mais {self.courant.decrire()} a été trouvé")
        return self.avancer()

    def attendre_fin_ligne_apres(self, mot):
        """Après « alors », « faire », etc., le bloc commence à la ligne suivante."""
        if self.courant.type == NL:
            self.avancer()
            return
        if self.courant.type == FIN_FICHIER:
            raise self.erreur(f"bloc attendu après « {mot} »", incomplet=True)
        raise self.erreur(
            f"fin de ligne attendue après « {mot} », mais "
            f"{self.courant.decrire()} a été trouvé",
            conseil="le contenu du bloc commence à la ligne suivante")

    def fin_instruction(self):
        if self.courant.type == NL:
            self.avancer()
        elif self.courant.type != FIN_FICHIER:
            raise self.erreur(
                f"fin de ligne attendue après l'instruction, mais "
                f"{self.courant.decrire()} a été trouvé",
                conseil="écrivez une seule instruction par ligne")

    def nom_declare(self, role) -> Jeton:
        jeton = self.courant
        if jeton.type == IDENT:
            return self.avancer()
        if jeton.type == MOTCLE:
            raise self.erreur(
                f"« {jeton.valeur} » est un mot réservé de K+ et ne peut pas "
                f"servir de {role}", conseil="choisissez un autre nom")
        raise self.erreur(f"{role} attendu, mais {jeton.decrire()} a été trouvé")

    # --- programme et blocs -----------------------------------------------------

    def programme(self) -> ast.Programme:
        instructions = []
        self.sauter_fins_ligne()
        while self.courant.type != FIN_FICHIER:
            instructions.append(self.instruction())
            self.fin_instruction()
            self.sauter_fins_ligne()
        return ast.Programme(1, 1, instructions)

    def bloc(self, fermants, ouvrant: Jeton, nom_bloc: str) -> list:
        """Lit des instructions jusqu'à l'un des mots-clés « fermants »."""
        instructions = []
        self.sauter_fins_ligne()
        while not self.est_motcle(*fermants):
            if self.courant.type == FIN_FICHIER:
                raise ErreurSyntaxe(
                    f"le bloc « {nom_bloc} » ouvert ici n'est jamais fermé "
                    f"par « fin »", ouvrant.ligne, ouvrant.colonne,
                    incomplet=True)
            instructions.append(self.instruction())
            self.fin_instruction()
            self.sauter_fins_ligne()
        return instructions

    # --- instructions -------------------------------------------------------------

    def instruction(self):
        jeton = self.courant
        if jeton.type == MOTCLE:
            mot = jeton.valeur
            if mot in ("variable", "constante"):
                return self.declaration()
            if mot == "si":
                return self.si()
            if mot == "tant":
                return self.tant_que()
            if mot == "pour":
                return self.pour()
            if mot == "fonction":
                return self.fonction()
            if mot == "essayer":
                return self.essayer()
            if mot == "retourner":
                self.avancer()
                valeur = None if self.est_fin_ligne() else self.expression()
                return ast.Retourner(jeton.ligne, jeton.colonne, valeur)
            if mot == "arreter":
                self.avancer()
                return ast.Arreter(jeton.ligne, jeton.colonne)
            if mot == "continuer":
                self.avancer()
                return ast.Continuer(jeton.ligne, jeton.colonne)
            if mot == "utiliser":
                self.avancer()
                nom = self.nom_declare("nom de bibliothèque")
                return ast.Utiliser(jeton.ligne, jeton.colonne, nom.valeur)
            if mot == "lever":
                self.avancer()
                return ast.Lever(jeton.ligne, jeton.colonne, self.expression())
            if mot == "fin":
                raise self.erreur("« fin » inattendu : aucun bloc n'est ouvert ici")
            if mot == "sinon":
                raise self.erreur(
                    "« sinon » inattendu : il doit suivre le bloc d'un « si »")
            if mot == "attraper":
                raise self.erreur(
                    "« attraper » inattendu : il doit suivre un bloc « essayer »")

        debut = self.courant
        expression = self.expression()
        if self.est_symbole("="):
            egal = self.avancer()
            if not self.est_cible(expression):
                raise self.erreur(
                    "on ne peut donner une valeur qu'à une variable ou à un "
                    "élément de liste", jeton=egal,
                    conseil="pour comparer deux valeurs, écrivez ==")
            valeur = self.expression()
            return ast.Affectation(debut.ligne, debut.colonne, expression,
                                   valeur)
        return ast.InstructionExpression(debut.ligne, debut.colonne, expression)

    def est_cible(self, noeud) -> bool:
        if isinstance(noeud, ast.Nom):
            return True
        if isinstance(noeud, ast.AccesIndice):
            return self.est_cible(noeud.objet)
        return False

    def declaration(self):
        mot = self.avancer()
        constante = mot.valeur == "constante"
        role = "nom de constante" if constante else "nom de variable"
        nom = self.nom_declare(role)
        if not self.est_symbole("="):
            raise self.erreur(
                f"« = » attendu après « {nom.valeur} » : une {mot.valeur} "
                f"doit recevoir une valeur",
                conseil=f"exemple : {mot.valeur} {nom.valeur} = nul")
        self.avancer()
        valeur = self.expression()
        return ast.Declaration(mot.ligne, mot.colonne, nom.valeur, valeur,
                               constante)

    def si(self):
        jeton_si = self.avancer()
        branches = []
        condition = self.expression()
        self.attendre_motcle("alors", "« alors » attendu après la condition")
        self.attendre_fin_ligne_apres("alors")
        corps = self.bloc(("fin", "sinon"), jeton_si, "si")
        branches.append((condition, corps))
        sinon = None
        while self.est_motcle("sinon"):
            jeton_sinon = self.avancer()
            if self.est_motcle("si"):
                self.avancer()
                condition = self.expression()
                self.attendre_motcle("alors", "« alors » attendu après la condition")
                self.attendre_fin_ligne_apres("alors")
                corps = self.bloc(("fin", "sinon"), jeton_si, "si")
                branches.append((condition, corps))
            else:
                self.attendre_fin_ligne_apres("sinon")
                sinon = self.bloc(("fin", "sinon"), jeton_si, "si")
                if self.est_motcle("sinon"):
                    raise self.erreur(
                        "un seul « sinon » est permis, et il doit être le dernier",
                        conseil="pour une autre condition, écrivez « sinon si ... alors » "
                                "avant le « sinon » final")
                break
        self.avancer()  # fin
        return ast.Si(jeton_si.ligne, jeton_si.colonne, branches, sinon)

    def tant_que(self):
        jeton = self.avancer()
        self.attendre_motcle("que", "« que » attendu après « tant »",
                             conseil="écrivez : tant que condition faire")
        condition = self.expression()
        self.attendre_motcle("faire", "« faire » attendu après la condition")
        self.attendre_fin_ligne_apres("faire")
        corps = self.bloc(("fin",), jeton, "tant que")
        self.avancer()
        return ast.TantQue(jeton.ligne, jeton.colonne, condition, corps)

    def pour(self):
        jeton = self.avancer()
        if self.est_motcle("chaque"):
            self.avancer()
            variable = self.nom_declare("nom de variable")
            self.attendre_motcle("dans", "« dans » attendu après le nom de la variable",
                                 conseil="écrivez : pour chaque x dans liste faire")
            iterable = self.expression()
            self.attendre_motcle("faire", "« faire » attendu")
            self.attendre_fin_ligne_apres("faire")
            corps = self.bloc(("fin",), jeton, "pour chaque")
            self.avancer()
            return ast.PourChaque(jeton.ligne, jeton.colonne, variable.valeur,
                                  iterable, corps)

        variable = self.nom_declare("nom de variable")
        self.attendre_motcle("de", "« de » attendu après le nom de la variable",
                             conseil="écrivez : pour i de 1 à 10 faire")
        debut = self.expression()
        conseil = None
        if self.courant.type == IDENT and self.courant.valeur in ("a", "A"):
            conseil = "écrivez « à » avec un accent : pour i de 1 à 10 faire"
        self.attendre_motcle("à", "« à » attendu après la valeur de départ",
                             conseil=conseil)
        fin = self.expression()
        pas = None
        if self.est_motcle("pas"):
            self.avancer()
            pas = self.expression()
        self.attendre_motcle("faire", "« faire » attendu")
        self.attendre_fin_ligne_apres("faire")
        corps = self.bloc(("fin",), jeton, "pour")
        self.avancer()
        return ast.Pour(jeton.ligne, jeton.colonne, variable.valeur, debut,
                        fin, pas, corps)

    def fonction(self):
        jeton = self.avancer()
        nom = self.nom_declare("nom de fonction")
        ouvrant = self.attendre_symbole(
            "(", f"« ( » attendu après le nom de la fonction « {nom.valeur} »")
        parametres = []
        if not self.est_symbole(")"):
            while True:
                parametre = self.nom_declare("nom de paramètre")
                if parametre.valeur in parametres:
                    raise self.erreur(
                        f"le paramètre « {parametre.valeur} » apparaît deux fois",
                        jeton=parametre)
                parametres.append(parametre.valeur)
                if not self.est_symbole(","):
                    break
                self.avancer()
        self.attendre_symbole(")", "« ) » ou « , » attendu dans la liste des "
                              "paramètres", ouvrant)
        self.attendre_fin_ligne_apres(")")
        corps = self.bloc(("fin",), jeton, "fonction")
        self.avancer()
        return ast.DefinitionFonction(jeton.ligne, jeton.colonne, nom.valeur,
                                      parametres, corps)

    def essayer(self):
        jeton = self.avancer()
        self.attendre_fin_ligne_apres("essayer")
        corps = self.bloc(("attraper", "fin"), jeton, "essayer")
        if self.est_motcle("fin"):
            raise self.erreur(
                "« attraper » attendu avant « fin » : un bloc « essayer » "
                "doit avoir une partie « attraper »")
        self.avancer()  # attraper
        nom_erreur = None
        if not self.est_fin_ligne():
            nom_erreur = self.nom_declare("nom de variable").valeur
        self.attendre_fin_ligne_apres("attraper")
        gestionnaire = self.bloc(("fin",), jeton, "essayer")
        self.avancer()
        return ast.Essayer(jeton.ligne, jeton.colonne, corps, nom_erreur,
                           gestionnaire)

    # --- expressions --------------------------------------------------------------

    def expression(self):
        return self.ou()

    def ou(self):
        gauche = self.et()
        while self.est_motcle("ou"):
            op = self.avancer()
            gauche = ast.OperationLogique(op.ligne, op.colonne, "ou", gauche,
                                          self.et())
        return gauche

    def et(self):
        gauche = self.non()
        while self.est_motcle("et"):
            op = self.avancer()
            gauche = ast.OperationLogique(op.ligne, op.colonne, "et", gauche,
                                          self.non())
        return gauche

    def non(self):
        if self.est_motcle("non"):
            op = self.avancer()
            return ast.OperationUnaire(op.ligne, op.colonne, "non", self.non())
        return self.comparaison()

    def comparaison(self):
        gauche = self.addition()
        if self.est_symbole(*OPERATEURS_COMPARAISON):
            op = self.avancer()
            gauche = ast.OperationBinaire(op.ligne, op.colonne, op.valeur,
                                          gauche, self.addition())
            if self.est_symbole(*OPERATEURS_COMPARAISON):
                raise self.erreur(
                    "les comparaisons ne peuvent pas s'enchaîner",
                    conseil="écrivez par exemple : a < b et b < c")
        return gauche

    def addition(self):
        gauche = self.multiplication()
        while self.est_symbole("+", "-"):
            op = self.avancer()
            gauche = ast.OperationBinaire(op.ligne, op.colonne, op.valeur,
                                          gauche, self.multiplication())
        return gauche

    def multiplication(self):
        gauche = self.unaire()
        while self.est_symbole("*", "/", "%"):
            op = self.avancer()
            gauche = ast.OperationBinaire(op.ligne, op.colonne, op.valeur,
                                          gauche, self.unaire())
        return gauche

    def unaire(self):
        if self.est_symbole("-", "+"):
            op = self.avancer()
            return ast.OperationUnaire(op.ligne, op.colonne, op.valeur,
                                       self.unaire())
        return self.puissance()

    def puissance(self):
        base = self.postfixe()
        if self.est_symbole("^"):
            op = self.avancer()
            # unaire() rappelle puissance() : associativité à droite.
            return ast.OperationBinaire(op.ligne, op.colonne, "^", base,
                                        self.unaire())
        return base

    def postfixe(self):
        expression = self.primaire()
        while True:
            if self.est_symbole("("):
                ouvrant = self.avancer()
                arguments = []
                if not self.est_symbole(")"):
                    arguments.append(self.expression())
                    while self.est_symbole(","):
                        self.avancer()
                        arguments.append(self.expression())
                self.attendre_symbole(
                    ")", "« ) » ou « , » attendu dans les arguments", ouvrant)
                expression = ast.Appel(expression.ligne, expression.colonne,
                                       expression, arguments)
            elif self.est_symbole("["):
                ouvrant = self.avancer()
                indice = self.expression()
                self.attendre_symbole("]", "« ] » attendu après l'indice", ouvrant)
                expression = ast.AccesIndice(ouvrant.ligne, ouvrant.colonne,
                                             expression, indice)
            else:
                return expression

    def primaire(self):
        jeton = self.courant
        if jeton.type in (ENTIER, DECIMAL, TEXTE):
            self.avancer()
            return ast.Litteral(jeton.ligne, jeton.colonne, jeton.valeur)
        if jeton.type == MOTCLE and jeton.valeur in ("vrai", "faux", "nul"):
            self.avancer()
            valeur = {"vrai": True, "faux": False, "nul": None}[jeton.valeur]
            return ast.Litteral(jeton.ligne, jeton.colonne, valeur)
        if jeton.type == IDENT:
            self.avancer()
            return ast.Nom(jeton.ligne, jeton.colonne, jeton.valeur)
        if self.est_symbole("("):
            ouvrant = self.avancer()
            expression = self.expression()
            self.attendre_symbole(")", "« ) » attendu", ouvrant)
            return expression
        if self.est_symbole("["):
            ouvrant = self.avancer()
            elements = []
            while not self.est_symbole("]"):
                elements.append(self.expression())
                if not self.est_symbole(","):
                    break
                self.avancer()
            self.attendre_symbole("]", "« ] » ou « , » attendu dans la liste",
                                  ouvrant)
            return ast.ListeLitterale(ouvrant.ligne, ouvrant.colonne, elements)

        conseil = None
        if jeton.type == MOTCLE:
            conseil = f"« {jeton.valeur} » est un mot réservé de K+"
        raise self.erreur(
            f"expression attendue, mais {jeton.decrire()} a été trouvé",
            conseil=conseil)


def analyser_syntaxe(jetons: list[Jeton]) -> ast.Programme:
    return Parser(jetons).programme()

fichiers.kplus/pont.py:
"""Pont entre le navigateur et le moteur K+.

Ce module est chargé dans Pyodide (Python dans le navigateur) par K+ Studio
(studio/travailleur.js), par les sites créés avec « kplus --site » et par UPL
Code Académie. Il n'utilise que le moteur K+ réel : rien n'est simulé.
Il est aussi testé sous Python normal (tests/test_studio.py, tests/test_web.py).

Les résultats sont renvoyés en JSON pour passer facilement vers JavaScript.
"""

import json
import time

import kplus
from kplus.erreurs import ErreurKPlus, SignalQuitter, formater_erreur

TAILLE_PAQUET = 4096          # caractères envoyés d'un coup au navigateur
DELAI_PAQUET = 0.05           # secondes maximum avant d'envoyer
SORTIE_MAX = 1_000_000        # au-delà, la sortie est tronquée


def version() -> str:
    return kplus.__version__


def decrire_erreur(erreur: ErreurKPlus, source: str) -> dict:
    return {
        "categorie": erreur.categorie,
        "nom": erreur.nom_affiche,
        "message": erreur.message,
        "ligne": erreur.ligne,
        "colonne": erreur.colonne,
        "conseil": erreur.conseil,
        "pile": [{"fonction": nom, "ligne": ligne} for nom, ligne in erreur.pile],
        "texte": formater_erreur(erreur, source),
    }


def verifier(source: str) -> str:
    """Analyse le programme sans l'exécuter."""
    try:
        kplus.analyser(source)
    except ErreurKPlus as e:
        return json.dumps({"ok": False, "erreur": decrire_erreur(e, source)})
    return json.dumps({"ok": True})


class SortieStudio:
    """Reçoit ce qu'affiche le programme et l'envoie au navigateur par paquets."""

    def __init__(self, envoyer):
        self.envoyer = envoyer
        self.tampon = []
        self.taille_tampon = 0
        self.dernier_envoi = time.monotonic()
        self.total = 0
        self.tronquee = False

    def _ajouter(self, genre, texte):
        if self.tronquee:
            return
        if self.total + len(texte) > SORTIE_MAX:
            self.vider()
            self.tronquee = True
            self.envoyer("systeme", "\n[Sortie tronquée : plus d'un million de "
                                    "caractères affichés.]\n")
            return
        self.total += len(texte)
        if self.tampon and self.tampon[-1][0] == genre:
            self.tampon[-1][1].append(texte)
        else:
            self.tampon.append((genre, [texte]))
        self.taille_tampon += len(texte)
        maintenant = time.monotonic()
        if (self.taille_tampon >= TAILLE_PAQUET
                or maintenant - self.dernier_envoi >= DELAI_PAQUET):
            self.vider()

    def write(self, texte):
        self._ajouter("sortie", texte)
        return len(texte)

    def ecrire_entree(self, texte):
        self._ajouter("entree", texte)

    def flush(self):
        pass

    def vider(self):
        for genre, morceaux in self.tampon:
            self.envoyer(genre, "".join(morceaux))
        self.tampon = []
        self.taille_tampon = 0
        self.dernier_envoi = time.monotonic()


class EntreeStudio:
    """Réponses préparées par l'utilisateur dans le panneau « Entrée clavier ».

    Chaque réponse utilisée est réaffichée dans la console, comme si elle
    avait été tapée au clavier."""

    def __init__(self, texte, sortie: SortieStudio):
        self.lignes = texte.split("\n") if texte else []
        if self.lignes and self.lignes[-1] == "":
            self.lignes.pop()
        self.sortie = sortie

    def readline(self):
        if not self.lignes:
            return ""                     # fin des entrées : demander() renvoie nul
        ligne = self.lignes.pop(0)
        self.sortie.ecrire_entree(ligne + "\n")
        return ligne + "\n"


# Programme web en cours (« utiliser web ») : il reste vivant entre deux
# événements (clics, saisies, minuteries) pour garder ses variables.
_session = None


def executer(source: str, entree: str, envoyer) -> str:
    """Analyse puis exécute le programme. `envoyer(genre, texte)` reçoit la
    sortie au fur et à mesure (genre : "sortie", "entree" ou "systeme").

    Pour un programme web, le résultat contient aussi "web": true et les
    "commandes" qui construisent la page (voir kplus/web.py)."""
    global _session
    _session = None
    debut = time.monotonic()
    sortie = SortieStudio(envoyer)
    resultat = {"statut": "ok"}
    interpreteur = None
    try:
        programme = kplus.analyser(source)
        interpreteur = kplus.Interpreteur(sortie, EntreeStudio(entree, sortie))
        interpreteur.executer_programme(programme)
    except ErreurKPlus as e:
        resultat = {"statut": "erreur", "erreur": decrire_erreur(e, source)}
    except SignalQuitter:
        pass
    finally:
        sortie.vider()
    if interpreteur is not None and interpreteur.page is not None:
        resultat["web"] = True
        resultat["commandes"] = interpreteur.page.prendre_commandes()
        _session = (interpreteur, source)
    resultat["duree_ms"] = round((time.monotonic() - debut) * 1000)
    return json.dumps(resultat)


def evenement(identifiant: str, genre: str, valeurs: str, envoyer) -> str:
    """Transmet un événement de la page (clic, change, minuterie) au programme
    web en cours. `valeurs` : JSON du contenu actuel des champs."""
    from kplus import web
    if _session is None:
        return json.dumps({"statut": "ok", "commandes": []})
    interpreteur, source = _session
    sortie = SortieStudio(envoyer)
    interpreteur.sortie = sortie
    try:
        erreur = web.declencher(interpreteur, identifiant, genre, json.loads(valeurs or "{}"), source)
    finally:
        sortie.vider()
    resultat = {"statut": "erreur" if erreur else "ok",
                "commandes": interpreteur.page.prendre_commandes()}
    if erreur:
        resultat["texte_erreur"] = erreur
    return json.dumps(resultat)


def executer_test(source: str, entree: str) -> str:
    """Exécution d'un test d'exercice (UPL Code Académie) : sortie du programme,
    ou description de la page pour un programme web dont l'entrée est un
    scénario (voir kplus/scenario.py)."""
    from kplus.scenario import ErreurScenario, executer_test as executer
    debut = time.monotonic()
    try:
        sortie, erreur = executer(source, entree)
        resultat = {"statut": "ok", "sortie": sortie}
        if erreur is not None:
            resultat = {"statut": "erreur", "sortie": sortie, "erreur": decrire_erreur(erreur, source)}
    except ErreurKPlus as e:
        resultat = {"statut": "erreur", "sortie": "", "erreur": decrire_erreur(e, source)}
    except ErreurScenario as e:
        resultat = {"statut": "scenario", "sortie": "", "message": str(e)}
    except SignalQuitter:
        resultat = {"statut": "ok", "sortie": ""}
    resultat["duree_ms"] = round((time.monotonic() - debut) * 1000)
    return json.dumps(resultat)

fichiers.kplus/scenario.py:
"""Scénarios de test des pages K+ Web.

Un scénario simule un visiteur, puis décrit la page obtenue sous forme de
texte. Il permet de corriger automatiquement un exercice de site web (UPL
Code Académie) et de tester un site sans navigateur (« kplus --scenario »).

Actions, une par ligne :
    saisir "Étiquette du champ" "texte tapé"
    cliquer "Texte affiché"          (bouton, ligne, paragraphe… qui réagit au clic)
    minuterie 3                      (3 tours de toutes les minuteries actives)
    # commentaire

Description de la page, un élément par ligne, dans l'ordre d'affichage
(les éléments placés dans une liste ou une zone sont décalés de 2 espaces) :
    titre: Mes tâches
    champ: Nouvelle tâche = ""
    liste:
      ligne: Réviser
"""

import io
import re
import shlex

from . import analyser, web
from .erreurs import ErreurKPlus
from .interpreteur import Interpreteur
from .valeurs import representer


class ErreurScenario(Exception):
    """Action de scénario incorrecte (message destiné à l'auteur du scénario)."""


def _visibles(page):
    return [e for e in page.elements.values() if not e.supprime and e.genre != "minuterie"]


def decrire_page(page) -> str:
    """Description textuelle de la page, dans l'ordre d'affichage."""
    lignes = []

    def decrire(e, profondeur):
        retrait = "  " * profondeur
        if e.genre == "champ":
            lignes.append(f"{retrait}champ: {e.etiquette} = {representer(e.valeur, True)}")
        elif e.genre == "image":
            lignes.append(f"{retrait}image: {e.description}")
        elif e.genre == "lien":
            lignes.append(f"{retrait}lien: {e.texte} -> {e.adresse}")
        elif e.genre in ("liste", "zone"):
            lignes.append(f"{retrait}{e.genre}:")
        else:
            lignes.append(f"{retrait}{e.genre}: {e.texte}")
        for enfant in e.enfants:
            if not enfant.supprime:
                decrire(enfant, profondeur + 1)

    for e in _visibles(page):
        if e.parent is None:
            decrire(e, 0)
    return "\n".join(lignes) + ("\n" if lignes else "")


def _actions(scenario: str):
    for numero, ligne in enumerate(scenario.replace("\r\n", "\n").split("\n"), start=1):
        texte = ligne.strip()
        if not texte or texte.startswith("#"):
            continue
        try:
            morceaux = shlex.split(texte)
        except ValueError:
            raise ErreurScenario(f"scénario, ligne {numero} : guillemets mal fermés") from None
        yield numero, morceaux


def jouer(source: str, scenario: str, programme=None) -> str:
    """Exécute le programme, joue le scénario, renvoie la description finale de la page.

    Les erreurs K+ au démarrage sont levées normalement ; une erreur dans une
    action est ajoutée à la description (« erreur: … »), comme le bandeau
    rouge de la page.
    """
    interp = Interpreteur(io.StringIO(), io.StringIO(""))
    interp.executer_programme(programme or analyser(source))
    page = interp.page
    if page is None:
        raise ErreurScenario("ce programme ne crée pas de page web (« utiliser web » manquant)")
    erreurs = []

    def declencher(element, evenement):
        valeurs = {e.id: e.valeur for e in _visibles(page) if e.genre == "champ"}
        message = web.declencher(interp, element.id, evenement, valeurs)
        if message:
            erreurs.append(message.split("\n")[0])

    for numero, action in _actions(scenario):
        nom = action[0].lower()
        if nom == "saisir" and len(action) == 3:
            champs = [e for e in _visibles(page) if e.genre == "champ" and e.etiquette == action[1]]
            if not champs:
                raise ErreurScenario(f"scénario, ligne {numero} : aucun champ « {action[1]} »")
            champs[0].valeur = action[2]
            if "change" in champs[0].actions:
                declencher(champs[0], "change")
        elif nom == "cliquer" and len(action) == 2:
            cibles = [e for e in _visibles(page) if "clic" in e.actions and e.texte == action[1]]
            if not cibles:
                raise ErreurScenario(f"scénario, ligne {numero} : rien à cliquer avec le texte « {action[1]} »")
            declencher(cibles[0], "clic")
        elif nom == "minuterie" and len(action) == 2 and action[1].isdigit():
            for _ in range(int(action[1])):
                for e in [m for m in page.elements.values()
                          if m.genre == "minuterie" and not m.supprime]:
                    declencher(e, "minuterie")
        else:
            raise ErreurScenario(f"scénario, ligne {numero} : action inconnue « {' '.join(action)} » "
                                 f"(actions : saisir, cliquer, minuterie)")
    page.prendre_commandes()
    texte = decrire_page(page)
    for message in erreurs:
        texte += f"erreur: {message}\n"
    return texte


def executer_test(source: str, entree: str) -> tuple[str, ErreurKPlus | None]:
    """Exécution d'un test d'exercice : un programme web reçoit l'entrée comme
    scénario et renvoie la description de sa page ; un programme ordinaire est
    exécuté normalement avec l'entrée. Renvoie (sortie, erreur K+ éventuelle)."""
    programme = analyser(source)
    from . import ast
    if any(isinstance(i, ast.Utiliser) and i.bibliotheque == "web" for i in programme.instructions):
        return jouer(source, entree, programme), None
    sortie = io.StringIO()
    interp = Interpreteur(sortie, io.StringIO(entree))
    try:
        interp.executer_programme(programme)
    except ErreurKPlus as e:
        return sortie.getvalue(), e
    return sortie.getvalue(), None

fichiers.kplus/valeurs.py:
"""Valeurs de K+ et leur représentation.

Correspondance entre les types K+ et Python :
    entier   -> int        décimal  -> float     texte -> str
    booléen  -> bool       nul      -> None      liste -> list
    fonction -> FonctionUtilisateur ou FonctionNative

Attention : en Python, bool est un sous-type de int. On teste donc toujours
« type(v) is int » et jamais « isinstance(v, int) ».
"""


class FonctionUtilisateur:
    """Fonction écrite en K+ avec « fonction ... fin »."""

    __slots__ = ("nom", "parametres", "corps", "fermeture")

    def __init__(self, nom, parametres, corps, fermeture):
        self.nom = nom
        self.parametres = parametres
        self.corps = corps
        self.fermeture = fermeture      # environnement de définition


class FonctionNative:
    """Fonction fournie par K+ (afficher, longueur, ...)."""

    __slots__ = ("nom", "arite_min", "arite_max", "implementation")

    def __init__(self, nom, arite_min, arite_max, implementation):
        self.nom = nom
        self.arite_min = arite_min
        self.arite_max = arite_max      # None = pas de limite
        self.implementation = implementation


class Element:
    """Morceau d'une page web (« utiliser web ») : titre, bouton, champ…
    Le modèle de la page est géré par kplus/web.py."""

    __slots__ = ("id", "genre", "texte", "valeur", "etiquette", "adresse",
                 "description", "parent", "enfants", "actions", "supprime",
                 "ligne")

    def __init__(self, ident, genre, texte="", ligne=None):
        self.id = ident
        self.genre = genre              # titre, bouton, champ, liste, ligne…
        self.texte = texte
        self.valeur = ""                # contenu d'un champ
        self.etiquette = ""
        self.adresse = ""
        self.description = ""
        self.parent = None
        self.enfants = []
        self.actions = {}               # « clic », « change », « minuterie »
        self.supprime = False
        self.ligne = ligne              # ligne du programme qui l'a créé


def est_nombre(v) -> bool:
    return type(v) is int or type(v) is float


def est_fonction(v) -> bool:
    return isinstance(v, (FonctionUtilisateur, FonctionNative))


def nom_type(v) -> str:
    t = type(v)
    if t is bool:
        return "booléen"
    if t is int:
        return "entier"
    if t is float:
        return "décimal"
    if t is str:
        return "texte"
    if v is None:
        return "nul"
    if t is list:
        return "liste"
    if est_fonction(v):
        return "fonction"
    if t is Element:
        return "élément"
    raise TypeError(f"valeur Python inattendue : {v!r}")  # bogue interne


ARTICLES = {
    "élément": "un élément",
    "booléen": "un booléen", "entier": "un entier", "décimal": "un décimal",
    "texte": "un texte", "nul": "nul", "liste": "une liste",
    "fonction": "une fonction",
}


def decrire_type(v) -> str:
    """« un entier », « une liste », ... pour les messages d'erreur."""
    return ARTICLES[nom_type(v)]


def _texte_entre_guillemets(t: str) -> str:
    t = (t.replace("\\", "\\\\").replace('"', '\\"')
         .replace("\n", "\\n").replace("\t", "\\t"))
    return f'"{t}"'


def representer(v, imbrique: bool = False, _en_cours=None) -> str:
    """Représentation textuelle d'une valeur (spécification §4.2).

    imbrique=True : la valeur est dans une liste, les textes sont alors
    affichés entre guillemets.
    """
    t = type(v)
    if t is bool:
        return "vrai" if v else "faux"
    if v is None:
        return "nul"
    if t is int:
        return str(v)
    if t is float:
        return repr(v)
    if t is str:
        return _texte_entre_guillemets(v) if imbrique else v
    if t is list:
        en_cours = _en_cours if _en_cours is not None else set()
        if id(v) in en_cours:
            return "[...]"                  # liste qui se contient elle-même
        en_cours.add(id(v))
        try:
            # Boucle simple (pas de générateur) : la récursion reste
            # entièrement en Python, ce qui la rend sûre aussi dans Pyodide.
            morceaux = []
            for element in v:
                morceaux.append(representer(element, True, en_cours))
            return "[" + ", ".join(morceaux) + "]"
        finally:
            en_cours.discard(id(v))
    if est_fonction(v):
        return f"<fonction {v.nom}>"
    if t is Element:
        nom = v.etiquette if v.genre == "champ" else v.texte
        return f"<élément {v.genre} « {nom} »>" if nom else f"<élément {v.genre}>"
    raise TypeError(f"valeur Python inattendue : {v!r}")  # bogue interne


def egal(a, b) -> bool:
    """Égalité K+ (opérateur ==) : ne provoque jamais d'erreur."""
    if est_nombre(a) and est_nombre(b):
        return a == b
    if type(a) is not type(b):
        return False
    if type(a) is list:
        if a is b:
            return True
        if len(a) != len(b):
            return False
        for i in range(len(a)):           # boucle simple : voir representer()
            if not egal(a[i], b[i]):
                return False
        return True
    if est_fonction(a):
        return a is b
    return a == b

fichiers.kplus/verificateur.py:
"""Vérifications statiques, faites sur l'AST avant l'exécution.

Elles détectent les erreurs de structure qui ne dépendent pas des valeurs :
- « retourner » hors d'une fonction ;
- « arreter » / « continuer » hors d'une boucle ;
- une ligne contenant une expression sans effet (par exemple « x == 5 »).
"""

from . import ast
from .erreurs import ErreurSyntaxe


class Verificateur:
    def __init__(self, interactif: bool = False):
        self.interactif = interactif

    def verifier(self, programme: ast.Programme):
        self.bloc(programme.instructions, dans_fonction=False,
                  dans_boucle=False, global_=True)

    def bloc(self, instructions, dans_fonction, dans_boucle, global_=False):
        for instruction in instructions:
            self.instruction(instruction, dans_fonction, dans_boucle, global_)

    def instruction(self, n, dans_fonction, dans_boucle, global_):
        if isinstance(n, ast.InstructionExpression):
            if not isinstance(n.expression, ast.Appel) and not (
                    self.interactif and global_):
                conseil = "utilisez cette valeur, par exemple : afficher(...)"
                e = n.expression
                if isinstance(e, ast.OperationBinaire) and e.operateur == "==":
                    conseil = "pour donner une valeur, écrivez = (un seul signe égal)"
                raise ErreurSyntaxe("cette expression n'a aucun effet",
                                    n.ligne, n.colonne, conseil)
        elif isinstance(n, ast.Utiliser):
            if not global_:
                raise ErreurSyntaxe(
                    "« utiliser » doit être écrit au niveau principal du programme, "
                    "pas dans un bloc", n.ligne, n.colonne,
                    "placez « utiliser web » au début du programme")
        elif isinstance(n, ast.Retourner):
            if not dans_fonction:
                raise ErreurSyntaxe(
                    "« retourner » ne peut être utilisé que dans une fonction",
                    n.ligne, n.colonne)
        elif isinstance(n, (ast.Arreter, ast.Continuer)):
            if not dans_boucle:
                mot = "arreter" if isinstance(n, ast.Arreter) else "continuer"
                raise ErreurSyntaxe(
                    f"« {mot} » ne peut être utilisé que dans une boucle",
                    n.ligne, n.colonne)
        elif isinstance(n, ast.Si):
            for _, corps in n.branches:
                self.bloc(corps, dans_fonction, dans_boucle)
            if n.sinon is not None:
                self.bloc(n.sinon, dans_fonction, dans_boucle)
        elif isinstance(n, (ast.TantQue, ast.Pour, ast.PourChaque)):
            self.bloc(n.corps, dans_fonction, True)
        elif isinstance(n, ast.DefinitionFonction):
            # Une fonction ne « voit » pas la boucle qui l'entoure.
            self.bloc(n.corps, True, False)
        elif isinstance(n, ast.Essayer):
            self.bloc(n.corps, dans_fonction, dans_boucle)
            self.bloc(n.gestionnaire, dans_fonction, dans_boucle)


def verifier(programme: ast.Programme, interactif: bool = False):
    Verificateur(interactif).verifier(programme)

fichiers.kplus/web.py:
"""Bibliothèque web de K+ (« utiliser web »).

Spécification : docs/specification/kplus-web-0.2.md.

Le moteur ne touche jamais directement la page du navigateur. Il tient un
MODÈLE de la page (des objets Element) et produit des COMMANDES : créer un
élément, changer un texte, supprimer… Le navigateur (K+ Studio, site exporté)
applique ces commandes et renvoie les événements (clics, saisies, minuteries).

Ce découpage rend la bibliothèque testable sans navigateur, et sûre : les
textes sont toujours affichés comme du texte, jamais interprétés comme du HTML.
"""

import re

from .erreurs import (
    ErreurExecution, ErreurType, ErreurValeur, SignalQuitter, formater_erreur,
)
from .valeurs import (
    Element, FonctionNative, FonctionUtilisateur, decrire_type, est_fonction,
)

COULEURS = {
    "rouge": "#d62828", "vert": "#2a9d4b", "bleu": "#1d4ed8",
    "jaune": "#f4c20d", "orange": "#f77f00", "violet": "#7b2cbf",
    "rose": "#e5579b", "noir": "#111111", "blanc": "#ffffff", "gris": "#6b7280",
}
MOTIF_COULEUR = re.compile(r"#[0-9a-fA-F]{6}")
INTERVALLE_MIN = 100          # millisecondes, pour toutes_les()
ELEMENTS_MAX = 10_000         # protection contre une boucle qui crée sans fin

GENRES_TEXTE = ("titre", "sous_titre", "paragraphe", "bouton", "ligne", "lien")


class Page:
    """Modèle de la page et file des commandes à envoyer au navigateur."""

    def __init__(self):
        self.elements = {}
        self.compteur = 0
        self.commandes = []

    def emettre(self, **commande):
        self.commandes.append(commande)

    def prendre_commandes(self):
        commandes, self.commandes = self.commandes, []
        return commandes

    def nouveau(self, interp, genre, texte="", parent=None, visible=True, **attributs):
        if len(self.elements) >= ELEMENTS_MAX:
            raise ErreurValeur(f"trop d'éléments dans la page (plus de {ELEMENTS_MAX})",
                               conseil="vérifiez qu'une boucle ne crée pas des éléments sans fin")
        self.compteur += 1
        ligne = getattr(getattr(interp, "noeud_appel", None), "ligne", None)
        e = Element(f"e{self.compteur}", genre, texte, ligne)
        for cle, valeur in attributs.items():
            setattr(e, cle, valeur)
        self.elements[e.id] = e
        if parent is not None:
            e.parent = parent
            parent.enfants.append(e)
        if visible:
            self.emettre(op="creer", id=e.id, genre=genre, texte=texte,
                         parent=parent.id if parent else None, **attributs)
        return e

    def retirer(self, e):
        """Marque un élément et ses descendants comme supprimés."""
        e.supprime = True
        for enfant in e.enfants:
            self.retirer(enfant)
        e.enfants = []


# --- Vérification des arguments ---------------------------------------------

def _texte(fonction, v, position="le texte"):
    if type(v) is not str:
        raise ErreurType(f"{fonction}() attend un texte comme {position}, pas {decrire_type(v)}",
                         conseil="convertissez la valeur avec texte(...)")
    return v


def _element(fonction, v, genres=None, quoi="un élément"):
    if type(v) is not Element:
        raise ErreurType(f"{fonction}() attend {quoi}, pas {decrire_type(v)}")
    if v.supprime:
        raise ErreurValeur(f"{fonction}() : cet élément a été supprimé de la page")
    if genres is not None and v.genre not in genres:
        raise ErreurType(f"{fonction}() attend {quoi}, pas un élément {v.genre}")
    return v


def _action(fonction, v):
    if not est_fonction(v):
        raise ErreurType(f"{fonction}() attend une fonction comme action, pas {decrire_type(v)}",
                         conseil="donnez le nom d'une fonction, sans parenthèses : "
                                 "bouton(\"OK\", ma_fonction)")
    if type(v) is FonctionUtilisateur and len(v.parametres) > 1:
        raise ErreurType(f"la fonction « {v.nom} » utilisée comme action doit avoir "
                         f"0 ou 1 paramètre, pas {len(v.parametres)}")
    return v


def _couleur(fonction, v):
    _texte(fonction, v, "couleur")
    nom = v.strip().lower()
    if nom in COULEURS:
        return COULEURS[nom]
    if MOTIF_COULEUR.fullmatch(nom):
        return nom
    raise ErreurValeur(f"couleur inconnue : \"{v}\"",
                       conseil="couleurs possibles : " + ", ".join(COULEURS) + ", ou un code #rrggbb")


def _adresse(fonction, v, images=False):
    _texte(fonction, v, "adresse")
    adresse = v.strip()
    schema = re.match(r"([a-zA-Z][a-zA-Z0-9+.-]*):", adresse)
    if schema is None:
        if adresse and not adresse.startswith("//"):
            return adresse                       # adresse relative : photo.jpg
    elif schema.group(1).lower() in ("http", "https"):
        return adresse
    elif images and adresse.lower().startswith("data:image/"):
        return adresse
    raise ErreurValeur(f"adresse refusée : \"{v}\"",
                       conseil="utilisez une adresse qui commence par https:// "
                               "(ou un nom de fichier, comme photo.jpg)")


def _page(interp):
    return interp.page


# --- Fonctions : créer --------------------------------------------------------

def titre(interp, args):
    return _page(interp).nouveau(interp, "titre", _texte("titre", args[0]))


def sous_titre(interp, args):
    return _page(interp).nouveau(interp, "sous_titre", _texte("sous_titre", args[0]))


def paragraphe(interp, args):
    return _page(interp).nouveau(interp, "paragraphe", _texte("paragraphe", args[0]))


def bouton(interp, args):
    action = _action("bouton", args[1])
    e = _page(interp).nouveau(interp, "bouton", _texte("bouton", args[0]))
    e.actions["clic"] = action
    _page(interp).emettre(op="ecouter", id=e.id, evenement="clic")
    return e


def champ(interp, args):
    return _page(interp).nouveau(interp, "champ", etiquette=_texte("champ", args[0], "étiquette"))


def liste(interp, args):
    return _page(interp).nouveau(interp, "liste")


def ajouter_ligne(interp, args):
    parent = _element("ajouter_ligne", args[0], ("liste",), "une liste créée par liste()")
    return _page(interp).nouveau(interp, "ligne", _texte("ajouter_ligne", args[1]), parent=parent)


def image(interp, args):
    adresse = _adresse("image", args[0], images=True)
    description = _texte("image", args[1], "description")
    return _page(interp).nouveau(interp, "image", adresse=adresse, description=description)


def lien(interp, args):
    texte_lien = _texte("lien", args[0])
    return _page(interp).nouveau(interp, "lien", texte_lien, adresse=_adresse("lien", args[1]))


def zone(interp, args):
    return _page(interp).nouveau(interp, "zone")


def placer(interp, args):
    e = _element("placer", args[0], quoi="un élément")
    z = _element("placer", args[1], ("zone",), "une zone créée par zone()")
    if e.genre in ("ligne", "minuterie"):
        raise ErreurType(f"placer() ne peut pas déplacer un élément {e.genre}")
    parent = z
    while parent is not None:
        if parent is e:
            raise ErreurValeur("placer() : on ne peut pas placer une zone dans elle-même")
        parent = parent.parent
    if e.parent is not None:
        e.parent.enfants.remove(e)
    e.parent = z
    z.enfants.append(e)
    _page(interp).emettre(op="deplacer", id=e.id, parent=z.id)
    return None


# --- Fonctions : lire et modifier ---------------------------------------------

def valeur(interp, args):
    return _element("valeur", args[0], ("champ",), "un champ créé par champ()").valeur


def changer_valeur(interp, args):
    e = _element("changer_valeur", args[0], ("champ",), "un champ créé par champ()")
    e.valeur = _texte("changer_valeur", args[1])
    _page(interp).emettre(op="valeur", id=e.id, valeur=e.valeur)
    return None


def texte_de(interp, args):
    e = _element("texte_de", args[0])
    if e.genre == "champ":
        return e.valeur
    if e.genre == "image":
        return e.description
    return e.texte


def changer_texte(interp, args):
    e = _element("changer_texte", args[0], GENRES_TEXTE,
                 "un élément qui affiche un texte (titre, paragraphe, bouton, ligne, lien)")
    e.texte = _texte("changer_texte", args[1])
    _page(interp).emettre(op="texte", id=e.id, texte=e.texte)
    return None


def vider(interp, args):
    e = _element("vider", args[0])
    page = _page(interp)
    if e.genre in ("liste", "zone"):
        for enfant in list(e.enfants):
            page.retirer(enfant)
        e.enfants = []
        page.emettre(op="vider", id=e.id)
    elif e.genre == "champ":
        e.valeur = ""
        page.emettre(op="valeur", id=e.id, valeur="")
    elif e.genre in GENRES_TEXTE:
        e.texte = ""
        page.emettre(op="texte", id=e.id, texte="")
    else:
        raise ErreurType(f"vider() ne s'applique pas à un élément {e.genre}")
    return None


def supprimer(interp, args):
    e = _element("supprimer", args[0])
    page = _page(interp)
    if e.parent is not None:
        e.parent.enfants.remove(e)
    page.retirer(e)
    if e.genre == "minuterie":
        page.emettre(op="arreter_minuterie", id=e.id)
    else:
        page.emettre(op="supprimer", id=e.id)
    return None


def _visibilite(nom, visible):
    def fonction(interp, args):
        e = _element(nom, args[0])
        _page(interp).emettre(op="visible", id=e.id, visible=visible)
        return None
    return fonction


def _style(nom, propriete):
    def fonction(interp, args):
        e = _element(nom, args[0])
        _page(interp).emettre(op="style", id=e.id, propriete=propriete,
                              valeur=_couleur(nom, args[1]))
        return None
    return fonction


def titre_page(interp, args):
    _page(interp).emettre(op="titre_page", texte=_texte("titre_page", args[0]))
    return None


# --- Fonctions : réagir --------------------------------------------------------

def quand_clic(interp, args):
    e = _element("quand_clic", args[0])
    if e.genre == "minuterie":
        raise ErreurType("quand_clic() ne s'applique pas à une minuterie")
    e.actions["clic"] = _action("quand_clic", args[1])
    _page(interp).emettre(op="ecouter", id=e.id, evenement="clic")
    return None


def quand_change(interp, args):
    e = _element("quand_change", args[0], ("champ",), "un champ créé par champ()")
    e.actions["change"] = _action("quand_change", args[1])
    _page(interp).emettre(op="ecouter", id=e.id, evenement="change")
    return None


def toutes_les(interp, args):
    intervalle = args[0]
    if type(intervalle) is not int:
        raise ErreurType(f"toutes_les() attend un nombre entier de millisecondes, "
                         f"pas {decrire_type(intervalle)}")
    if intervalle < INTERVALLE_MIN:
        raise ErreurValeur(f"toutes_les() : l'intervalle doit être d'au moins "
                           f"{INTERVALLE_MIN} millisecondes")
    action = _action("toutes_les", args[1])
    page = _page(interp)
    e = page.nouveau(interp, "minuterie", visible=False)
    e.actions["minuterie"] = action
    page.emettre(op="minuterie", id=e.id, intervalle=intervalle)
    return e


def arreter_minuterie(interp, args):
    e = _element("arreter_minuterie", args[0], ("minuterie",), "une minuterie créée par toutes_les()")
    e.supprime = True
    _page(interp).emettre(op="arreter_minuterie", id=e.id)
    return None


